    shampoo: ["шампунь", "Shampoo — от хинди chāmpo, «нажимать, массировать»; слово пришло в английский из Индии в XVIII веке и сначала означало массаж."],
    safari: ["сафари", "Safari на суахили значит «путешествие», а само слово заимствовано из арабского safar."],
    ski: ["лыжи", "Ski — норвежское слово, от древнескандинавского skíð, «деревянная плаха»."],
    sauna: ["сауна", "Sauna — финское слово; в Финляндии, где живёт около 5,5 млн человек, примерно три миллиона саун."],
    yogurt: ["йогурт", "Yogurt — турецкое yoğurt, родственное глаголу yoğurmak, «месить, сгущать»."],
    pajamas: ["пижама", "Pajamas — от персидского pāy-jāma, «одежда для ног», через хиндустани."],
